/* fusion : chaque championnat recoit un objet de saisons vide */
try{(function(){var SD=(typeof STANDINGS_DATA!=='undefined')&&STANDINGS_DATA;if(!SD||!SD.lookup)return;
var lk=SD.lookup; SD.countries=SD.countries||[];
var connus={}; SD.countries.forEach(function(c){connus[c.name]=1;});
Object.keys(NS_PAYS_A_VENIR).forEach(function(pays){
// 1) les championnats, avec des saisons vides : aucun classement invente
if(!lk[pays]){var o={};NS_PAYS_A_VENIR[pays].forEach(function(lg){o[lg]={};});lk[pays]=o;}
// 2) la meme source alimente la liste centrale de l'ecran Classement
if(!connus[pays]){SD.countries.push({name:pays,
flag:(typeof TRFLAG!=='undefined'?TRFLAG(pays):'\ud83c\udf0d'),
leagueCount:NS_PAYS_A_VENIR[pays].length,aVenir:true});connus[pays]=1;}});
SD.countries.sort(function(x,y){return x.name.localeCompare(y.name,'fr');});})();}catch(e){}

const NS_RESOLVE_LEAGUE=function(nom){
try{
var norm=function(x){return (x||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim();};
var cible=norm(nom);
// coupes d'Europe (Champions League, Europa League, Conference League)
if(typeof EURO_COMPS!=='undefined'){
for(var i=0;i<EURO_COMPS.length;i++){if(norm(EURO_COMPS[i].name)===cible)return {kind:'euro',id:EURO_COMPS[i].id};}}
// competitions internationales (Coupe du Monde, EURO, Ligue des Nations...)
if(typeof INTL_COMPS!=='undefined'){
for(var j=0;j<INTL_COMPS.length;j++){if(norm(INTL_COMPS[j].name)===cible)return {kind:'intl',id:INTL_COMPS[j].id};}}
// championnats nationaux
var lk=(typeof STANDINGS_DATA!=='undefined'&&STANDINGS_DATA.lookup)||{};
var exact=null, partiel=null;
Object.keys(lk).forEach(function(co){
Object.keys(lk[co]||{}).forEach(function(lg){
var n=norm(lg);
if(n===cible){ if(!exact||(typeof TRFLAG!=='undefined'&&TRFLAG(co)!=='\ud83c\udf0d')) exact={kind:'domestic',country:co,league:lg}; }
else if(!partiel&&(n.indexOf(cible+' ')===0)){ partiel={kind:'domestic',country:co,league:lg}; }
});});
return exact||partiel||null;
}catch(e){return null;}
};


