// ── TEAM DETAIL SCREEN ────────────────────────────────────────────────────────

// ── Sections hommes / femmes : jamais melangees ────────────────────────────
// Saison a ouvrir par defaut : la plus recente REELLEMENT disputee.
// Une saison a peine ouverte (France 2026/27) contient les equipes mais
// zero match : l'afficher donnerait un tableau alphabetique a zero point.
// Beaucoup de championnats se jouent en poules : Ligue 2 algerienne
// (Est / Ouest), 1a Divisio andorrane (saison reguliere puis play-offs).
// Aplaties en un seul tableau, les places repartent a 1 au milieu.
// Deux cas : le groupe est nomme, ou il faut le deduire du rang qui repart.
const NS_POULES=function(lignes){
if(!lignes||!lignes.length)return [];
// Deux pieges distincts :
//  - un championnat a poules doit etre coupe (Ligue 2 algerienne Est/Ouest) ;
//  - la source renvoie parfois un tableau UNIQUE dans le desordre
//    (Liga 2017/18 : 1, 2, 4, 3, 5, 7, 9, 6...).
// Couper des que le rang redescend confondait les deux et fabriquait de
// faux groupes. Le vrai signal d'une nouvelle poule, c'est le retour du
// rang 1, ou un changement de nom de groupe.
var out=[],cour=null;
var nommes=lignes.some(function(r){return r.groupe;});
for(var i=0;i<lignes.length;i++){
var r=lignes[i];
var nom=r.groupe||null;
var rupture=!cour
 ||(nommes&&cour.nom!==nom)
 ||(r.rank===1&&cour.lignes.length>0);
if(rupture){cour={nom:nom,lignes:[]};out.push(cour);}
cour.lignes.push(r);}
// la source n'est pas toujours triee : on remet chaque poule dans l'ordre
out.forEach(function(g){g.lignes=g.lignes.slice().sort(function(a,b){
return (a.rank||0)-(b.rank||0);});});
// Une phase pas encore disputee (Clausura a venir, play-offs a jouer)
// renvoie toutes ses equipes a zero point : elle n'apprend rien et fait
// croire a un classement casse. On ne l'affiche pas, sauf si aucune
// phase n'a demarre.
var joue=out.filter(function(g){
return g.lignes.reduce(function(a,r){return a+(r.played||0);},0)>0;});
if(joue.length)out=joue;
if(out.length>1){
var vus={};
out.forEach(function(g,i){
if(!g.nom){g.nom='Groupe '+(i+1);return;}
vus[g.nom]=(vus[g.nom]||0)+1;});
var cpt={};
out.forEach(function(g){
if(vus[g.nom]>1){cpt[g.nom]=(cpt[g.nom]||0)+1;
g.nom=g.nom+' — groupe '+cpt[g.nom];}});}
return out;};
const NS_SAISON_DEFAUT=function(ligue){
if(!ligue)return null;
var k=Object.keys(ligue).sort().reverse();
for(var i=0;i<k.length;i++){
var lignes=ligue[k[i]]||[];
var joues=lignes.reduce(function(a,r){return a+(r.played||0);},0);
if(joues>0)return k[i];}
return k[0]||null;};
const NS_EST_FEMININ=function(nom){return /f[eé]minin|women|femenin|frauen|damallsvenskan|\bnwsl\b|\bwsl\b/i.test(String(nom||''));};
const NS_LIGUE_LBL=function(nom){var n=String(nom||'');
if(/^Premiere Ligue Feminine France$/i.test(n))return 'Première Ligue Féminine';
// le troisieme echelon francais prend le nom de Ligue 3
if(/^National 1$/i.test(n))return 'Ligue 3';
if(n==='League')return 'Pro League';
return n;};

